R,C=29,27
base=[[5]*C for _ in range(R)]
pat=[[3,6,1],[9,3,7],[6,5,5]]
# retain original pattern at rows 0..2, cols 1..3
for dr in range(3):
 for dc in range(3): base[dr][dc+1]=pat[dr][dc]
pts=[(1,6),(1,19),(2,11),(2,15),(3,24),(4,7),(5,3),(6,14),(6,18),(7,25),(8,4),(9,8),(9,15),(9,20),(11,1),(11,24),(12,12),(13,20),(14,4),(14,8),(14,15),(16,11),(16,21),(17,17),(17,25),(19,1),(19,8),(19,13),(22,15),(22,22),(23,6),(23,11),(24,18),(26,1),(26,13),(26,23),(27,9)]
# Compose stamps; count conflicts when two overlapping patterns demand differing colors.
owner={}; conflicts=[]
for i,(r,c) in enumerate(pts):
 for dr in range(3):
  for dc in range(3):
   rr,cc=r+dr-1,c+dc-1
   if 0<=rr<R and 0<=cc<C:
    v=pat[dr][dc]
    if (rr,cc) in owner and owner[(rr,cc)][0]!=v:
     conflicts.append((rr,cc,owner[(rr,cc)],(v,i)))
    owner[(rr,cc)]=(v,i)
for (r,c),(v,i) in owner.items(): base[r][c]=v
print('conflicts',len(conflicts),conflicts[:30])
for row in base: print('['+','.join(map(str,row))+'],')
